// Standard OpenAI rates, 30-minute cache, checked 2026-11-03.
// https://developers.openai.com/api/docs/models/gpt-6-luna
// https://developers.openai.com/api/docs/models/gpt-6.1-terra
export const browserModelEfforts = Object.freeze({
  "gpt-6.1-terra": ["low", "medium"],
  "gpt-6-luna": ["none", "low", "medium", "high", "xhigh", "max"],
});
export function validateModelSettings(config) {
  const model = config.model === undefined ? "gpt-6.1-terra" : config.model;
  if (!Object.hasOwn(browserModelEfforts, model))
    throw new TypeError("Unsupported browser Runner model");
  if (
    !browserModelEfforts[model].includes(
      config.reasoning === undefined ? "low" : config.reasoning,
    )
  )
    throw new TypeError(
      "Runner reasoning is unsupported for the selected model",
    );
  if (
    config.effortRecovery !== undefined &&
    typeof config.effortRecovery !== "boolean"
  )
    throw new TypeError("Runner effortRecovery must be boolean");
}
export function estimateCost(usage, model) {
  const rates =
    model === "gpt-6-luna"
      ? [0.1, 0.01, 0.125, 0.5]
      : model === "gpt-6.1-terra"
        ? [1, 0.05, 1.25, 5]
        : null;
  if (!rates) throw new TypeError("Unsupported Runner cost model");
  const input = usage.input_tokens ?? 0,
    output = usage.output_tokens ?? 0;
  const cached = usage.input_tokens_details?.cached_tokens ?? 0;
  const written = usage.input_tokens_details?.cache_write_tokens ?? 0;
  return (
    ((Math.max(0, input - cached - written) * rates[0] +
      cached * rates[1] +
      written * rates[2]) *
      (input > 272000 ? 2 : 1) +
      output * rates[3] * (input > 272000 ? 1.5 : 1)) /
    1e6
  );
}
